function firstNum(s){ const m=String(s||"").replace(/,/g,"").match(/\d+(\.\d+)?/); return m?Number(m[0]):NaN; }
const w=firstNum(dv.missed_calls_weekly), r=firstNum(dv.close_rate_pct), a=firstNum(dv.avg_job_value);
const missing=[];
if(!Number.isFinite(w)||w<=0||w>500) missing.push("missed_calls_weekly");
if(!Number.isFinite(r)||r<=0||r>100) missing.push("close_rate_pct");
if(!Number.isFinite(a)||a<=0||a>100000) missing.push("avg_job_value");
if(missing.length) return { ok:false, error:"missing_leak_inputs", missing };
const weekly=w*(r/100)*a;
const monthly=Math.floor(weekly*4.33/100)*100;
return { ok:true,
  weekly_leak:Math.floor(weekly).toLocaleString("en-US"),
  monthly_leak:monthly.toLocaleString("en-US"),
  inputs_used:{ missed_calls_weekly:w, close_rate_pct:r, avg_job_value:a } };
